import { defineConfig } from '@pulse-compute/pulse'

export default defineConfig((_scope) => ({
  pulse: {
    entry: 'src/index.ts',
    tests: 'tests/pulse.harness.ts',
    defaultProfile: 'local',
    strict: true,
  },
  local: {
    host: 'node',
    target: 'native',
    outDir: 'dist',
    dev: { host: '127.0.0.1', port: 8787 },
  },
}))

{
  "name": "@pulse-examples/01-hello-json",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "doctor": "pulse doctor",
    "inspect": "pulse inspect",
    "test": "pulse test",
    "dev": "pulse dev",
    "build": "pulse build"
  },
  "dependencies": {
    "@pulse-compute/pulse": "1.0.0-beta.9"
  },
  "devDependencies": {
    "@pulse-compute/cli": "1.0.0-beta.9",
    "typescript": "5.9.3"
  }
}

export default {
  cases: [
    {
      name: 'health',
      request: { path: '/health' },
      expect: { status: 200, json: { ok: true } },
    },
    {
      name: 'hello',
      request: { path: '/hello' },
      expect: {
        status: 200,
        json: { message: 'hello from Pulse' },
      },
    },
    {
      name: 'missing',
      request: { path: '/missing' },
      expect: { status: 404, text: 'not found' },
    },
  ],
}

